import{_ as a,o,c as l,j as e}from"./chunks/framework.BdHuibk5.js";const m=JSON.parse('{"title":"“揍性”，“稳稳的”!","description":"好久没晒过日记了，走出学校后，环境变了，人也在变。偶尔迷茫，偶尔犯浑，但生活还是要稳稳地往前走。","frontmatter":{"title":"“揍性”，“稳稳的”!","date":"2011-11-20 17:13","category":"diary","tags":["心情"],"slug":"steady-and-composed","layout":"blog-post","description":"好久没晒过日记了，走出学校后，环境变了，人也在变。偶尔迷茫，偶尔犯浑，但生活还是要稳稳地往前走。"},"headers":[],"relativePath":"blog/steady-and-composed.md","filePath":"blog/posts/diary/steady-and-composed.md","lastUpdated":1789447662000}'),s={name:"blog/steady-and-composed.md"};function d(n,t,p,r,c,u){return o(),l("div",null,[...t[0]||(t[0]=[e("p",null,"好久没晒过日记了，发现自己还是比较喜欢把很多东西都藏起来，藏得越深越好。走出学校后，跟以前认识的同学、朋友聊天，好多人说我变了，于是我问他们我变成啥狗样了，然后他们对我说：描述不来，只是感觉。",-1),e("p",null,"也许吧，随着环境的不同，咱总得学着适应环境，可环境也会影响咱的。但江山易改，本性难移不是。",-1),e("p",null,"发现自己有时会变得迷茫，不知所措，有时候无意间变得慌，没理由地慌，有的时候会突然想很多事，不管是之前在学校里发生的事，还是出学校后的零零总总，让我好生怀念和留恋。",-1),e("p",null,"昨天帮朋友搬家时去了趟餐厅，陌生感强压过了曾经的那些点滴。原来，我早就不属于这里了。为何有时会变得如此感性，我也不知道，但我相信，一个重感情的人，同样也是一个会珍惜感情之人。",-1),e("p",null,"前两天有一朋友面试时不小心手机被偷了，我真不知道说什么好，只希望他能挺过去，尽快把手机卡先补上，不然，被偷走的可不仅仅只是一个手机了，更是自己的前途。祝他一切顺利！",-1),e("p",null,"这几天好事也是有的，我也开心，9.17号前两天，我打过几个电话给那些个啃了好久书为司考准备的人，我当时还瞎嚷嚷着说替他们去灵隐寺烧高香，可谁知道我那时还哪有多余的钱去灵隐呐……不过，总共打了仨电话，这仨人竟然全过了，这事我自己还是觉得挺有趣的，真心地高兴。",-1),e("p",null,"周末也会去打打球，虽然都跟一群不认识的人，但至少我还是开心的，我还是挺会打理生活的（至少我是这么觉得，嘿嘿）。所以，偶尔犯浑是正常的事，比如现在，脑子就不是很好使。",-1),e("p",null,"坐过山车往下俯冲时，我突然觉得，生活嘛，有的时候还是需要多多寻找些刺激、新鲜事，这样，才会活得多姿多彩！",-1),e("p",null,"平时开开心心做自己喜欢做的事，有那么些个小目标，然后去奋斗，去完成他，也会为生活添加不少的乐趣。加油吧，你，我，还有你们！",-1)])])}const y=a(s,[["render",d]]);export{m as __pageData,y as default};
